mapper.select:
SELECT public > 0 as ispublic, showsolution, caseAmount
FROM problem
WHERE name = #{name}

SELECT name, cnname, mode, start, end, public > 0 AS publicContest, note, password
FROM contest
WHERE name = #{name}

mapper.update:
UPDATE contest SET
                   cnname   = #{cnname},
                   mode     = #{mode},
                   start    = #{start},
                   end      = #{end},
                   public   = #{publicContest},
                   note     = #{note},
                   password = #{password}
WHERE name = #{name}

mapper.delete:
DELETE FROM contest_problem
WHERE contest_name = #{contestName}
  AND problem_name = #{problemName}

mapper.select:
SELECT score FROM contest_problem
WHERE contest_name = #{contestName}
  AND problem_name = #{problemName}

SELECT contest_name AS contestName,
       user_name AS userName,
       problem_name AS problemName,
       score,
       attempts AS times,
       last_submit as lastSubmit
FROM contest_board
WHERE contest_name = #{contestName}
  AND user_name    = #{userName}
  AND problem_name = #{problemName}

mapper.update:
UPDATE contest_board SET
                         score    = #{score},
                         attempts = #{times},
                         last_submit = CURRENT_TIMESTAMP
WHERE contest_name = #{contestName}
  AND user_name    = #{userName}
  AND problem_name = #{problemName}
